CREATE TABLE cache_artifact_decl (attempt_id TEXT NOT NULL, ord INTEGER NOT NULL CHECK(ord>=0), path TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL, retention TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('project','restricted')), image_ref TEXT NOT NULL DEFAULT '', epoch INTEGER NOT NULL, declared_at INTEGER NOT NULL, PRIMARY KEY(attempt_id,ord));
CREATE TABLE cache_artifact (id TEXT PRIMARY KEY, project TEXT NOT NULL, run_id TEXT NOT NULL, job TEXT NOT NULL, attempt_id TEXT NOT NULL, revision TEXT NOT NULL, decl INTEGER NOT NULL, path TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, sha256 TEXT NOT NULL CHECK(length(sha256)=64), size INTEGER NOT NULL CHECK(size>=0), platform TEXT NOT NULL, runner_id TEXT NOT NULL, isolation TEXT NOT NULL, producer TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('project','restricted')), retention TEXT NOT NULL, release INTEGER NOT NULL CHECK(release IN (0,1)), epoch INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('staged','committed')), missing INTEGER NOT NULL DEFAULT 0 CHECK(missing IN (0,1)), image TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL DEFAULT 0, UNIQUE(attempt_id,name));
CREATE INDEX cache_artifact_attempt ON cache_artifact(attempt_id, decl);
CREATE INDEX cache_artifact_project ON cache_artifact(project, created_at DESC);
CREATE INDEX cache_artifact_run ON cache_artifact(run_id);
CREATE INDEX cache_artifact_expiry ON cache_artifact(expires_at) WHERE expires_at>0;
CREATE TRIGGER cache_artifact_immutable BEFORE UPDATE ON cache_artifact WHEN OLD.state='committed' AND (NEW.id IS NOT OLD.id OR NEW.project IS NOT OLD.project OR NEW.run_id IS NOT OLD.run_id OR NEW.job IS NOT OLD.job OR NEW.attempt_id IS NOT OLD.attempt_id OR NEW.revision IS NOT OLD.revision OR NEW.decl IS NOT OLD.decl OR NEW.path IS NOT OLD.path OR NEW.name IS NOT OLD.name OR NEW.kind IS NOT OLD.kind OR NEW.sha256 IS NOT OLD.sha256 OR NEW.size IS NOT OLD.size OR NEW.platform IS NOT OLD.platform OR NEW.runner_id IS NOT OLD.runner_id OR NEW.isolation IS NOT OLD.isolation OR NEW.producer IS NOT OLD.producer OR NEW.visibility IS NOT OLD.visibility OR NEW.retention IS NOT OLD.retention OR NEW.release IS NOT OLD.release OR NEW.epoch IS NOT OLD.epoch OR NEW.state IS NOT OLD.state OR NEW.image IS NOT OLD.image OR NEW.created_at IS NOT OLD.created_at) BEGIN SELECT RAISE(ABORT,'E712 immutable: a committed artifact record changes only expires_at and missing'); END;
CREATE TRIGGER cache_artifact_guard AFTER UPDATE OF state ON attempt WHEN OLD.state='finalizing' AND NEW.state='passed' AND (EXISTS(SELECT 1 FROM cache_artifact WHERE attempt_id=NEW.id AND state<>'committed') OR EXISTS(SELECT 1 FROM cache_artifact_decl d WHERE d.attempt_id=NEW.id AND NOT EXISTS(SELECT 1 FROM cache_artifact a WHERE a.attempt_id=d.attempt_id AND a.decl=d.ord AND a.state='committed'))) BEGIN UPDATE attempt SET state='failed', failure_class='infra' WHERE id=NEW.id; END;
CREATE TABLE cache_artifact_reserve (attempt_id TEXT PRIMARY KEY, project TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>=0), epoch INTEGER NOT NULL, reserved_at INTEGER NOT NULL);
CREATE TRIGGER cache_artifact_unpassed AFTER UPDATE OF state ON attempt WHEN NEW.state IN ('failed','cancelled') AND OLD.state IN ('running','finalizing','passed','needs-operator') BEGIN DELETE FROM cache_artifact WHERE attempt_id=NEW.id; DELETE FROM cache_artifact_reserve WHERE attempt_id=NEW.id; END;
